import java.util.*;

public class GenericLab {
    public static void main(String[] args) {
        List<String> words = new ArrayList<>(List.of("cherry", "apple", "banana"));
        System.out.println("Max word: " + max(words)); // bounded generic method

        Pair<Integer, String> pair = new Pair<>(1, "one");
        System.out.println(pair);

        // Wildcard: read-only view (producer)
        List<? extends Number> numbers = List.of(1, 2.5, 3L);
        double sum = 0;
        for (Number n : numbers) sum += n.doubleValue();
        System.out.println("Sum: " + sum);
    }

    static <T extends Comparable<T>> T max(List<T> list) {
        T best = list.get(0);
        for (T item : list) {
            if (item.compareTo(best) > 0) best = item;
        }
        return best;
    }

    record Pair<A, B>(A first, B second) {}
}

