import java.util.*;

public class SetMapLab {
    public static void main(String[] args) {
        Set<String> guests = new LinkedHashSet<>(List.of("Alice", "Bob", "Alice"));
        System.out.println("Guests (order kept): " + guests);

        TreeSet<Integer> nums = new TreeSet<>(List.of(5, 1, 9, 3, 5));
        System.out.println("Sorted set: " + nums + " | floor(6)=" + nums.floor(6));

        Map<String, Integer> stock = new HashMap<>();
        stock.put("apple", 10);
        stock.put("pear", 4);
        stock.putIfAbsent("apple", 99); // ignored, 10 stays
        stock.computeIfAbsent("plum", k -> 0); // adds plum -> 0
        stock.merge("apple", 5, Integer::sum); // apple -> 15
        System.out.println("Stock: " + stock);

        Map<String, Integer> scores = new TreeMap<>();
        scores.put("zoe", 3); scores.put("amy", 9);
        System.out.println("Sorted keys: " + scores.keySet());
    }
}

