import java.util.*;

public class SortLab {
    record Player(String name, int score) implements Comparable<Player> {
        @Override
        public int compareTo(Player o) {
            return Integer.compare(this.score, o.score); // natural: score asc
        }
    }

    public static void main(String[] args) {
        List<Player> players = new ArrayList<>(List.of(
            new Player("Ada", 95), new Player("Bob", 88), new Player("Eve", 95)));

        players.sort(Comparator.comparing(Player::score)
                .reversed()
                .thenComparing(Player::name));
        System.out.println("By score desc, then name: " + players);

        players.sort(Comparator.naturalOrder());
        System.out.println("Natural (score asc): " + players);
    }
}

