    enum OrderStatus {
        NEW(0), PAID(1), SHIPPED(2), DELIVERED(3);
        final int step;
        OrderStatus(int step) { this.step = step; }
    }

    public static void main(String[] args) {
        Day today = Day.FRIDAY;
        System.out.println(today + " weekend? " + today.isWeekend());

        for (Day d : Day.values()) {
            System.out.println(d + " (" + d.ordinal() + ")");
        }

        Day parsed = Day.valueOf("MONDAY");
        System.out.println("Parsed: " + parsed);

        OrderStatus status = OrderStatus.SHIPPED;
        System.out.println("Status step: " + status.step);

        switch (today) {
            case SATURDAY, SUNDAY -> System.out.println("Rest!");
            default -> System.out.println("Work.");
        }
    }
}

