import java.util.*;
import java.util.function.*;

public class LambdaLab {
    public static void main(String[] args) {
        List<String> names = new ArrayList<>(List.of("Ada", "Grace", "Linus", "Dennis"));
        names.removeIf(name -> name.length() < 5);          // Predicate
        names.replaceAll(String::toUpperCase);              // UnaryOperator
        names.forEach(System.out::println);                 // Consumer

        Function<String, Integer> length = s -> s.length();
        System.out.println("length(ADA): " + length.apply("ADA"));

        Predicate<Integer> even = n -> n % 2 == 0;
        System.out.println("4 even? " + even.test(4) + " | 3 even? " + even.test(3));

        Supplier<Double> random = () -> Math.random();
        System.out.println("Random: " + random.get());

        BiFunction<Integer, Integer, Integer> add = (a, b) -> a + b;
        System.out.println("2+3 = " + add.apply(2, 3));

        int base = 10; // effectively final
        Function<Integer, Integer> withBase = n -> n + base;
        System.out.println("withBase(5) = " + withBase.apply(5));
    }
}

