import java.util.*;
import java.util.stream.*;

public class StreamLab {
    public static void main(String[] args) {
        List<String> names = List.of("Ada", "Grace", "Linus", "Dennis", "Ada", "Guy");

        List<String> result = names.stream()
                .filter(n -> n.length() >= 4)
                .map(String::toUpperCase)
                .distinct()
                .sorted()
                .toList();
        System.out.println(result); // [ADA, DENNIS, GRACE, LINUS]

        long count = names.stream().filter(n -> n.startsWith("G")).count();
        System.out.println("G names: " + count);

        int sum = IntStream.rangeClosed(1, 5).sum();
        System.out.println("1+2+3+4+5 = " + sum);

        int total = names.stream().reduce(0, (acc, n) -> acc + n.length(), Integer::sum);
        System.out.println("Total letters: " + total);

        names.stream().limit(2).forEach(System.out::println); // lazy: only 2 consumed
    }
}

