import java.util.*;
import java.util.stream.*;

public class CollectorsLab {
    public static void main(String[] args) {
        List<String> words = List.of("apple", "banana", "apricot", "cherry", "blueberry");

        Map<Character, List<String>> byFirst = words.stream()
                .collect(Collectors.groupingBy(w -> w.charAt(0)));
        System.out.println("By first letter: " + byFirst);

        Map<Integer, Long> byLength = words.stream()
                .collect(Collectors.groupingBy(String::length, Collectors.counting()));
        System.out.println("By length: " + byLength);

        Map<Boolean, List<String>> longWords = words.stream()
                .collect(Collectors.partitioningBy(w -> w.length() > 6));
        System.out.println("Long (>6): " + longWords.get(true));

        String joined = words.stream().collect(Collectors.joining(" | ", "[", "]"));
        System.out.println(joined);

        IntSummaryStatistics stats = words.stream().collect(Collectors.summarizingInt(String::length));
