import java.io.*;
import java.nio.file.*;

public class AdvancedExceptions {
    static class OrderNotFoundException extends RuntimeException {
        OrderNotFoundException(int id) { super("Order " + id + " not found"); }
    }

    static class StorageException extends RuntimeException {
        StorageException(String msg, Throwable cause) { super(msg, cause); }
    }

    static void loadOrder(int id) {
        if (id <= 0) throw new OrderNotFoundException(id);
        System.out.println("Loading order " + id);
    }

    static void writeData(String file, String data) {
        try (BufferedWriter w = Files.newBufferedWriter(Path.of(file))) {
            w.write(data);
            System.out.println("Wrote " + file);
        } catch (IOException e) {
            throw new StorageException("Could not write " + file, e); // chain!
        }
    }

    public static void main(String[] args) {
        try {
            loadOrder(-1);
        } catch (OrderNotFoundException e) {
            System.out.println(e.getMessage());
        }

        try {
            writeData("out.txt", "hello");
        } catch (StorageException e) {
            System.out.println("Failed, cause: " + e.getCause().getClass().getSimpleName());
        }

        try {
            int a = Integer.parseInt("x");
            int b = Integer.parseInt("y");
        } catch (NumberFormatException | NullPointerException e) { // multi-catch
            System.out.println("Multi-catch: " + e.getClass().getSimpleName());
        }
    }
}

