import java.lang.annotation.*;
import java.lang.reflect.*;

public class ReflectionLab {
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.METHOD)
    @interface Tag {
        String value();
    }

    static class Service {
        @Tag("core")
        public void start() {
            System.out.println("Service started");
        }

        @Tag("bonus")
        public void stop() {
            System.out.println("Service stopped");
        }

        private void hidden() {
            System.out.println("Secret method");
        }
    }

    public static void main(String[] args) throws Exception {
        Class<?> clazz = Service.class;
        System.out.println("Class: " + clazz.getName());

        // Run every method annotated with @Tag("core")
        for (Method m : clazz.getDeclaredMethods()) {
            Tag tag = m.getAnnotation(Tag.class);
            if (tag != null && tag.value().equals("core")) {
                m.invoke(new Service());
            }
        }

        // Invoke a private method
        Method hidden = clazz.getDeclaredMethod("hidden");
        hidden.setAccessible(true);
        hidden.invoke(new Service());

        // Introspect fields
        Field[] fields = clazz.getDeclaredFields();
        System.out.println("Fields: " + fields.length);
    }
}

