public class ThreadLab {
    public static void main(String[] args) throws InterruptedException {
        Runnable task = () -> {
            for (int i = 1; i <= 3; i++) {
                System.out.println(Thread.currentThread().getName() + " step " + i);
                try { Thread.sleep(50); } catch (InterruptedException e) { Thread.currentThread().interrupt(); }
            }
        };

        Thread t1 = new Thread(task, "Chef-A");
        Thread t2 = new Thread(task, "Chef-B");

        t1.start();
        t2.start();
        t1.join(); // wait for t1
        t2.join();
        System.out.println("All done. Main thread: " + Thread.currentThread().getName());

        // Lifecycle peek
        Thread idle = new Thread(() -> {});
        System.out.println("Before start: " + idle.getState()); // NEW
        idle.start();
        idle.join();
        System.out.println("After join: " + idle.getState());   // TERMINATED
    }
}

