import java.util.concurrent.atomic.*;

public class SyncLab {
    static int unsafe = 0;
    static AtomicInteger safe = new AtomicInteger();
    static int guarded = 0;
    static final Object lock = new Object();

    public static void main(String[] args) throws InterruptedException {
        Thread[] workers = new Thread[1000];
        for (int i = 0; i < workers.length; i++) {
            workers[i] = new Thread(() -> {
                for (int j = 0; j < 1000; j++) {
                    unsafe++;                 // races!
                    safe.incrementAndGet();   // atomic
                    synchronized (lock) {
                        guarded++;            // guarded
                    }
                }
            });
            workers[i].start();
        }
        for (Thread t : workers) t.join();

        System.out.println("Unsafe (racy):    " + unsafe);
        System.out.println("Atomic:           " + safe.get());
        System.out.println("Synchronized:     " + guarded);

        AtomicInteger counter = new AtomicInteger(5);
        System.out.println("getAndAdd: " + counter.getAndAdd(3) + " -> now " + counter.get());
        System.out.println("compareAndSet 8? " + counter.compareAndSet(8, 99));
    }
}

