import java.util.concurrent.*;

public class ExecutorLab {
    public static void main(String[] args) throws Exception {
        ExecutorService pool = Executors.newFixedThreadPool(4);

        Future<Integer> f1 = pool.submit(() -> 6 * 7);
        Future<Integer> f2 = pool.submit(() -> 20 + 22);
        System.out.println("f1: " + f1.get() + " | f2: " + f2.get());

        CompletableFuture<Integer> base = CompletableFuture.supplyAsync(() -> 21 * 2, pool);
        CompletableFuture<String> greeting = base
                .thenApply(n -> "The answer is " + n)
                .thenApply(String::toUpperCase);
        System.out.println(greeting.get());

        CompletableFuture<Integer> a = CompletableFuture.supplyAsync(() -> 100, pool);
        CompletableFuture<Integer> b = CompletableFuture.supplyAsync(() -> 50, pool);
        CompletableFuture<Integer> sum = a.thenCombine(b, Integer::sum);
        System.out.println("Combined: " + sum.get());

        CompletableFuture<String> risky = CompletableFuture
                .supplyAsync(() -> { if (true) throw new RuntimeException("boom"); return "x"; }, pool)
                .exceptionally(e -> "Recovered: " + e.getMessage());
        System.out.println(risky.get());

        pool.shutdown();
    }
}

