import java.util.*;

public class JvmLab {
    public static void main(String[] args) {
        System.out.println("Java version:  " + Runtime.version());
        System.out.println("Available CPUs: " + Runtime.getRuntime().availableProcessors());

        // Heap observation
        Runtime rt = Runtime.getRuntime();
        long before = (rt.totalMemory() - rt.freeMemory()) / 1024 / 1024;

        List<int[]> junk = new ArrayList<>();
        for (int i = 0; i < 10_000; i++) junk.add(new int[1000]);

        long after = (rt.totalMemory() - rt.freeMemory()) / 1024 / 1024;
        System.out.println("Heap used before/after (MB): " + before + " -> " + after);
        System.out.println("Max heap (-Xmx): " + rt.maxMemory() / 1024 / 1024 + " MB");

        // String pool vs new
        String a = "duke";
        String b = "duke";
        String c = new String("duke");
        System.out.println("Literal == Literal: " + (a == b));     // true (pooled)
        System.out.println("Literal == new:     " + (a == c));     // false
        System.out.println("Literal .equals new: " + a.equals(c)); // true

        junk.clear(); // hint: these are now garbage, GC will clean up
        System.gc();  // politely asks the GC to run (usually ignored)
    }
}

