import java.sql.*;

public class JdbcLab {
    public static void main(String[] args) {
        // Requires a driver jar on the classpath (e.g., H2, Postgres).
        // Without one, you'll see ClassNotFoundException/No suitable driver —
        // add the driver dependency in Maven/Gradle (that's what the lesson covers).
        String url = "jdbc:h2:mem:test"; // in-memory H2: no server needed
        String user = "sa";
        String pass = "";

        String sql = "SELECT id, name FROM users WHERE age > ?";

        try (Connection conn = DriverManager.getConnection(url, user, pass);
             PreparedStatement ps = conn.prepareStatement(sql)) {

            conn.setAutoCommit(false); // transaction start
            try (Statement setup = conn.createStatement()) {
                setup.execute("CREATE TABLE users (id INT PRIMARY KEY, name VARCHAR(50), age INT)");
                setup.execute("INSERT INTO users VALUES (1, 'Ada', 36), (2, 'Grace', 15), (3, 'Linus', 55)");
            }

            ps.setInt(1, 18); // parameters are set safely, never concatenated
            try (ResultSet rs = ps.executeQuery()) {
                while (rs.next()) {
                    System.out.println(rs.getInt("id") + ": " + rs.getString("name"));
                }
            }
            conn.commit();
            System.out.println("Transaction committed.");

        } catch (SQLException e) {
            System.out.println("DB error (" + e.getSQLState() + "): " + e.getMessage());
        }
    }
}

