import java.util.*;

public class JsonLab {
    record Person(String name, int age) {}

    // Mini JSON serializer for records with simple fields (educational only;
    // production code uses Jackson/Gson).
    static String toJson(Object o) {
        if (o instanceof String s) return "\"" + s.replace("\"", "\\\"") + "\"";
        if (o instanceof Integer i) return String.valueOf(i);
        if (o instanceof Person p) return "{\"name\": " + toJson(p.name()) + ", \"age\": " + p.age() + "}";
        if (o instanceof List<?> list) {
            StringJoiner joiner = new StringJoiner(", ", "[", "]");
            list.forEach(item -> joiner.add(toJson(item)));
            return joiner.toString();
        }
        return "null";
    }

