import java.util.*;
import java.util.function.*;

public class PatternLab {
    // --- Strategy: swap the algorithm at runtime ---
    interface Discount {
        double apply(double price);
    }

    static double checkout(double price, Discount strategy) {
        return strategy.apply(price);
    }

    // --- Builder for a config-heavy object ---
    static class Config {
        final String host;
        final int port;
        final boolean verbose;
        private Config(String host, int port, boolean verbose) {
            this.host = host; this.port = port; this.verbose = verbose;
        }
        static class Builder {
            private String host = "localhost";
            private int port = 8080;
            private boolean verbose;
            Builder host(String h) { this.host = h; return this; }
            Builder port(int p) { this.port = p; return this; }
            Builder verbose() { this.verbose = true; return this; }
            Config build() { return new Config(host, port, verbose); }
        }
    }

    // --- Observer-ish: callbacks via lambdas ---
    static class Alarm {
        private final List<Runnable> listeners = new ArrayList<>();
        void onRing(Runnable r) { listeners.add(r); }
        void ring() { listeners.forEach(Runnable::run); }
    }

    public static void main(String[] args) {
        System.out.println("Strategy: " + checkout(100, price -> price * 0.9));
        System.out.println("Strategy 2: " + checkout(100, price -> Math.max(0, price - 20)));

        Config cfg = new Config.Builder().host("api.example.com").port(443).verbose().build();
        System.out.println("Builder: " + cfg.host + ":" + cfg.port + " verbose=" + cfg.verbose);

        Alarm alarm = new Alarm();
        alarm.onRing(() -> System.out.println("Observer: wake up!"));
        alarm.ring();
    }
}

