import java.util.*;

public class SpringLab {
    // A 20-line mini-DI container showing the ESSENCE of Spring's IoC:
    // beans declare their needs; a container creates and wires them.
    record Database() {
        String query() { return "rows from DB"; }
    }

    record UserService(Database db) { // dependency injected via constructor
        String listUsers() { return db.query(); }
    }

    static class MiniContext {
        private final Map<Class<?>, Object> beans = new HashMap<>();

        <T> void register(Class<T> type, T instance) { beans.put(type, instance); }

        @SuppressWarnings("unchecked")
        <T> T get(Class<T> type) {
            return (T) beans.get(type);
        }
    }

    public static void main(String[] args) {
        MiniContext context = new MiniContext();
        Database db = new Database();
        context.register(Database.class, db);
        context.register(UserService.class, new UserService(context.get(Database.class)));

        UserService service = context.get(UserService.class);
        System.out.println("Service got its dependency injected: " + service.listUsers());
        System.out.println("Spring does this with @Component + constructor injection at scale.");
    }
}

