import java.util.*;

public class UnitTestLab {
    static class Calculator {
        int divide(int a, int b) {
            if (b == 0) throw new IllegalArgumentException("b must not be 0");
            return a / b;
        }

        List<Integer> evensUpTo(int n) {
            List<Integer> out = new ArrayList<>();
            for (int i = 0; i <= n; i++) if (i % 2 == 0) out.add(i);
            return out;
        }
    }

    // Mini test runner mimicking JUnit 5 (real projects add junit-jupiter to deps):
    static int passed = 0, failed = 0;

    static void assertEquals(Object expected, Object actual, String name) {
        if (Objects.equals(expected, actual)) { passed++; System.out.println("PASS " + name); }
        else { failed++; System.out.println("FAIL " + name + " — expected " + expected + " got " + actual); }
    }

    static void assertThrowsLike(Runnable r, String name) {
        try { r.run(); failed++; System.out.println("FAIL " + name + " — no exception thrown"); }
        catch (IllegalArgumentException e) { passed++; System.out.println("PASS " + name); }
    }

    public static void main(String[] args) {
        Calculator calc = new Calculator();
        assertEquals(5, calc.divide(10, 2), "divide happy path");
        assertThrowsLike(() -> calc.divide(1, 0), "divide by zero throws");
        assertEquals(List.of(0, 2, 4), calc.evensUpTo(4), "evens up to 4");
        assertEquals(List.of(0), calc.evensUpTo(1), "evens up to 1");

        System.out.println("\nPassed: " + passed + ", Failed: " + failed);
        System.out.println("In real projects: @Test + assertEquals + assertThrows via JUnit 5.");
    }
}

