import java.util.*;

public class SolidLab {
    // --- SRP: one reason to change per class ---
    record Order(String id, double total) {}

    interface OrderStorage {
        void save(Order order);
    }

    static class InMemoryStorage implements OrderStorage {
        private final List<Order> orders = new ArrayList<>();
        public void save(Order order) { orders.add(order); }
        List<Order> all() { return orders; }
    }

    interface Notifier {
        void notify(String message);
    }

    static class EmailNotifier implements Notifier {
        public void notify(String message) { System.out.println("[email] " + message); }
    }

    // --- OCP + DI: extend behavior by adding classes, never editing this one ---
    static class Checkout {
        private final OrderStorage storage;
        private final Notifier notifier;

        Checkout(OrderStorage storage, Notifier notifier) {
            this.storage = storage;
            this.notifier = notifier;
        }

        void place(Order order) {
            storage.save(order);                     // depends on interfaces
            notifier.notify("Order " + order.id() + " placed");
        }
    }

    public static void main(String[] args) {
        Checkout checkout = new Checkout(new InMemoryStorage(), new EmailNotifier());
        checkout.place(new Order("A1", 49.99));
        System.out.println("Checkout depends only on interfaces — swap storage or notifier freely.");
    }
}

