public class CleanCodeLab {
    // --- BEFORE: what does this do? ---
    static boolean check(int[] a, int n, int t) {
        boolean f = false;
        for (int i = 0; i < n; i++) {
            if (a[i] == t) {
                f = true;
                break;
            }
        }
        return f;
    }

    // --- AFTER: intention-revealing ---
    static boolean contains(int[] values, int target) {
        for (int value : values) {
            if (value == target) {
                return true;
            }
        }
        return false;
    }

    static final int MAX_RETRIES = 3; // named, not magic

    public static void main(String[] args) {
