public class PerfLab {
    public static void main(String[] args) {
        int n = 100_000;

        // Slow: string concatenation in a loop (creates n Strings)
        long start = System.nanoTime();
        String slow = "";
        for (int i = 0; i < n; i++) slow += "x";
        long slowMs = (System.nanoTime() - start) / 1_000_000;

        // Fast: StringBuilder (one buffer)
        start = System.nanoTime();
        StringBuilder fast = new StringBuilder(n); // sized capacity
        for (int i = 0; i < n; i++) fast.append("x");
        long fastMs = (System.nanoTime() - start) / 1_000_000;

        System.out.println("Concat: " + slowMs + " ms");
        System.out.println("Builder: " + fastMs + " ms");
        System.out.println("Same result: " + slow.equals(fast.toString()));

        // Boxing vs primitives
        long sum = 0;
        for (int i = 0; i < 10_000_000; i++) sum += i;
        System.out.println("Primitive loop sum: " + sum);
    }
}

