public class ModernJava {
    // sealed hierarchy: the compiler knows ALL subtypes
    sealed interface Shape permits Circle, Rect {}
    record Circle(double r) implements Shape {}
    record Rect(double w, double h) implements Shape {}

    static double area(Shape s) {
        // Pattern matching for switch: no casts, exhaustive, no null cases missed
        return switch (s) {
            case Circle c -> Math.PI * c.r() * c.r();
            case Rect r -> r.w() * r.h();
        };
    }

    public static void main(String[] args) {
        var circle = new Circle(2.0);       // var: inferred type
        var rect = new Rect(3.0, 4.0);

        Object maybeCircle = circle;        // pattern matching for instanceof
        if (maybeCircle instanceof Circle c) {
            System.out.println("It's a circle, r=" + c.r() + " area=" + area(c));
        }

        String json = """
                {
                  "name": "Duke",
                  "level": 42
                }
                """;                       // text block: no escapes needed
        System.out.println(json.strip());

        System.out.println("Rect area: " + area(rect));
        System.out.println("Switch expression + pattern matching + records + var + text blocks: Java 21.");
    }
}

