import java.util.*;

public class InterviewLab {
    // FizzBuzz-style classic: print numbers 1..n; multiples of 3 -> Fizz,
    // of 5 -> Buzz, of both -> FizzBuzz. Shows clean logic + iteration.
    static void fizzBuzz(int n) {
        for (int i = 1; i <= n; i++) {
            String out = "";
            if (i % 3 == 0) out += "Fizz";
            if (i % 5 == 0) out += "Buzz";
            System.out.println(out.isEmpty() ? i : out);
        }
    }

    // Classic #2 answer in code: equals/hashCode contract
    static class Person {
        final String name;
        final int age;
        Person(String name, int age) { this.name = name; this.age = age; }
        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Person p)) return false;
            return age == p.age && name.equals(p.name);
        }
        @Override public int hashCode() { return Objects.hash(name, age); }
    }

    public static void main(String[] args) {
        fizzBuzz(15);

        Set<Person> people = new HashSet<>();
        people.add(new Person("Ada", 36));
        System.out.println("Contains equal object? " + people.contains(new Person("Ada", 36))); // true
    }
}

