import java.io.*;
import java.nio.file.*;
import java.time.*;
import java.util.*;
import java.util.stream.*;

public class ExpenseTracker {
    record Expense(LocalDate date, String category, double amount, String note) {
        static Expense parse(String line) {
            String[] parts = line.split(";");
            return new Expense(LocalDate.parse(parts[0]), parts[1],
                    Double.parseDouble(parts[2]), parts.length > 3 ? parts[3] : "");
        }
        String toLine() { return date + ";" + category + ";" + amount + ";" + note; }
    }

    static final Path FILE = Path.of("expenses.txt");

    static List<Expense> load() {
        if (!Files.exists(FILE)) return new ArrayList<>();
        try { return Files.readAllLines(FILE).stream().map(Expense::parse).toList(); }
        catch (IOException e) { System.out.println("Could not load: " + e.getMessage()); return new ArrayList<>(); }
    }

    static void save(List<Expense> expenses) {
        try { Files.writeString(FILE, expenses.stream().map(Expense::toLine).collect(Collectors.joining("\n"))); }
        catch (IOException e) { System.out.println("Could not save: " + e.getMessage()); }
    }

    public static void main(String[] args) {
        List<Expense> expenses = new ArrayList<>(load());

        expenses.add(new Expense(LocalDate.now(), "food", 12.50, "lunch"));
        expenses.add(new Expense(LocalDate.now().minusDays(1), "transport", 4.00, "bus"));
        expenses.add(new Expense(LocalDate.now().minusDays(2), "food", 8.75, "coffee"));
        save(expenses);

        Map<String, Double> byCategory = expenses.stream()
                .collect(Collectors.groupingBy(Expense::category, Collectors.summingDouble(Expense::amount)));
        byCategory.forEach((cat, total) -> System.out.printf("%s: %.2f%n", cat, total));

        double total = expenses.stream().mapToDouble(Expense::amount).sum();
        System.out.printf("Total: %.2f%n", total);
    }
}

